  loop
    select g.id into v_goal_id
    from goals g
    join regionals r on r.id = g.regional_id and r.code = v_item->>'rc'
    join areas a on a.id = g.area_id and a.code = v_item->>'ac'
    join indicators i on i.id = g.indicator_id and i.name = v_item->>'ind'
    join goal_cycles c on c.id = g.cycle_id and c.name = 'Ciclo 2026';

    if v_goal_id is null then
      raise notice 'goal nao encontrado: % / % / %', v_item->>'rc', v_item->>'ac', v_item->>'ind';
      continue;
    end if;

    for v_band in select * from jsonb_array_elements(v_item->'bands')
    loop
      insert into goal_ranges (goal_id, attainment_percentage, target_value, target_month)
      select v_goal_id, (v_band->>0)::numeric, (v_band->>1)::numeric,
             case when v_band->>2 = 'null' or v_band->2 is null then null else (v_band->>2)::int end
      where not exists (
        select 1 from goal_ranges gr2 where gr2.goal_id = v_goal_id and gr2.attainment_percentage = (v_band->>0)::numeric
      );
    end loop;

    if (v_item->>'real') is not null or (v_item->>'real_pct') is not null then
      insert into goal_results (goal_id, real_value, real_value_pct)
      select v_goal_id, (v_item->>'real')::numeric, (v_item->>'real_pct')::numeric
      where not exists (select 1 from goal_results gr3 where gr3.goal_id = v_goal_id);
    end if;
  end loop;
end $$;
